CREATE TABLE scim_configurations (tenant_id VARCHAR(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, user_id_attribute VARCHAR(256) NOT NULL, mapping LONGTEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,connection_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE scim_tokens (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, scopes TEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NULL, last_used_at BIGINT NULL, PRIMARY KEY (tenant_id,id), UNIQUE KEY scim_tokens_hash (tenant_id,token_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX scim_tokens_connection ON scim_tokens (tenant_id,connection_id);
CREATE TABLE directory_groups (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, name VARCHAR(128) NOT NULL, external_id VARCHAR(256) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE KEY directory_groups_name (tenant_id,connection_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE directory_group_members (tenant_id VARCHAR(64) NOT NULL, group_id VARBINARY(64) NOT NULL, user_id VARBINARY(1280) NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,group_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX directory_group_members_user ON directory_group_members (tenant_id,user_id);
CREATE TABLE directory_group_roles (tenant_id VARCHAR(64) NOT NULL, group_id VARBINARY(64) NOT NULL, role_id VARBINARY(255) NOT NULL, organization_id VARBINARY(64) NOT NULL, PRIMARY KEY (tenant_id,group_id,role_id,organization_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX directory_group_roles_role ON directory_group_roles (tenant_id,role_id);
